//! A fake live TV source on 127.0.0.1 for tests: M3U playlist, Xtream Codes API,
//! HDHomeRun (`discover.json`, `lineup.json`, UDP discovery) and XMLTV guide, with
//! endless real-time MPEG-TS streams generated by ffmpeg per connection.
//! Shared by the livetv and API tests (`#[path]`-included).
#![allow(dead_code)]

use std::io::Write as _;
use std::net::SocketAddr;
use std::process::Stdio;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

use axum::Router;
use axum::body::Body;
use axum::extract::{Path, Query, State};
use axum::http::{StatusCode, header};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use tokio::io::AsyncWriteExt;

pub const USER: &str = "max";
pub const PASSWORD: &str = "geheim";

#[derive(Clone)]
struct Shared {
    base: String,
    /// Stream connections currently open.
    streams: Arc<AtomicUsize>,
    /// Stream connections opened so far.
    opened: Arc<AtomicUsize>,
    /// Logo downloads.
    logos: Arc<AtomicUsize>,
}

pub struct FakeSource {
    pub base: String,
    /// UDP address answering HDHomeRun discovery requests.
    pub discovery: SocketAddr,
    streams: Arc<AtomicUsize>,
    opened: Arc<AtomicUsize>,
    logos: Arc<AtomicUsize>,
}

impl FakeSource {
    /// Logo downloads so far.
    pub fn logo_downloads(&self) -> usize {
        self.logos.load(Ordering::SeqCst)
    }

    /// Stream connections currently open.
    pub fn open_streams(&self) -> usize {
        self.streams.load(Ordering::SeqCst)
    }

    /// Stream connections opened so far (probes included).
    pub fn opened_streams(&self) -> usize {
        self.opened.load(Ordering::SeqCst)
    }

    pub fn url(&self, path: &str) -> String {
        format!("{}{path}", self.base)
    }
}

pub async fn start() -> FakeSource {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let shared = Shared {
        base: base.clone(),
        streams: Arc::default(),
        opened: Arc::default(),
        logos: Arc::default(),
    };
    let app = Router::new()
        .route("/playlist.m3u", get(playlist))
        .route("/guide.xml", get(guide))
        .route("/guide.xml.gz", get(guide_gz))
        .route("/discover.json", get(discover))
        .route("/lineup.json", get(lineup))
        .route("/auto/{channel}", get(hdhr_stream))
        .route("/player_api.php", get(xtream_api))
        .route("/live/{user}/{password}/{file}", get(xtream_stream))
        .route("/stream/{kind}/{file}", get(stream))
        .route("/logo/{file}", get(logo))
        .with_state(shared.clone());
    tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });

    let udp = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
    let discovery = udp.local_addr().unwrap();
    let reply = flixnet_livetv::hdhomerun::discover_reply(0x1013_ABCD, 2, &base);
    tokio::spawn(async move {
        let mut buf = [0u8; 1500];
        while let Ok((len, from)) = udp.recv_from(&mut buf).await {
            if flixnet_livetv::hdhomerun::is_discover_request(&buf[..len]) {
                let _ = udp.send_to(&reply, from).await;
            }
        }
    });

    FakeSource {
        base,
        discovery,
        streams: shared.streams,
        opened: shared.opened,
        logos: shared.logos,
    }
}

async fn playlist(State(s): State<Shared>) -> String {
    let base = &s.base;
    format!(
        "#EXTM3U url-tvg=\"{base}/guide.xml.gz\"
#EXTINF:-1 tvg-id=\"daserste.de\" tvg-name=\"Das Erste HD\" tvg-logo=\"{base}/logo/ard.png\" tvg-chno=\"1\" group-title=\"Vollprogramm\",Das Erste HD
{base}/stream/h264/1.ts
#EXTINF:-1 tvg-chno=\"2\" group-title=\"Vollprogramm\",ZDF HD
{base}/stream/h264/2.ts
#EXTINF:-1 tvg-chno=\"3\" group-title=\"Kultur\",DE: arte
{base}/stream/mpeg2/3.ts
#EXTINF:-1 tvg-chno=\"4\",Kaputt TV
{base}/missing.ts
"
    )
}

